<script setup lang="ts">
import{ref,watch,onBeforeUnmount}from'vue';import{History,RefreshCw}from'@lucide/vue';
const props=defineProps<{visitId:string;orderId:string;version:number;requirementsTotal:number;handoversTotal:number;reviewsTotal:number}>(),emit=defineEmits(['denied']);
const expanded=ref(false),items=ref<any[]>([]),people=ref<Record<string,string>>({}),next=ref<string|null>(null),total=ref(0),asOf=ref(''),limit=ref(25),eventType=ref('all'),requirementId=ref(''),requirementVersion=ref<number|null>(null),loading=ref(false),error=ref(''),loaded=ref(false);let generation=0,controller:AbortController|null=null;
const labels:Record<string,string>={all:'全部办理',requirement:'医生加工要求',sent:'实际送出',received:'实际接收',progress:'进度与预计返回',review:'医生临床核对',problem:'问题与依据失效',treatment_change:'治疗依据更正'},time=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未登记',short=(s:string)=>s?s.slice(0,8).toUpperCase():'无',match=(x:any)=>x===true?'已核实相符':x===false?'不相符':'尚未核实相符';
function clear(){generation++;controller?.abort();controller=null;items.value=[];people.value={};next.value=null;total.value=0;asOf.value='';loading.value=false;loaded.value=false;error.value='';}
watch(()=>[props.visitId,props.orderId,props.version],()=>{clear();expanded.value=false;requirementId.value='';requirementVersion.value=null;});
async function load(more=false){if(loading.value)return;if(!more)clear();const gen=++generation;controller=new AbortController();const own=controller;loading.value=true;error.value='';const timer=setTimeout(()=>own.abort(),15000),q=new URLSearchParams({eventType:eventType.value,limit:String(limit.value)});if(requirementId.value)q.set('requirementId',requirementId.value);if(more&&next.value)q.set('cursor',next.value);
 try{const r=await fetch(`/api/v1/care/visits/${props.visitId}/labs/${props.orderId}/history?${q}`,{credentials:'same-origin',signal:own.signal}),b=await r.json().catch(()=>({}));if(gen!==generation)return;if(!r.ok){if(r.status===401||r.status===403){clear();expanded.value=false;emit('denied',r.status);return;}throw Error(b.message||'读取加工历史失败。');}items.value=more?[...items.value,...b.items]:b.items;people.value={...people.value,...Object.fromEntries(b.people.map((p:any)=>[p.id,p.name]))};next.value=b.nextCursor;total.value=b.total;asOf.value=b.asOf;loaded.value=true;
 }catch(e){if(gen===generation)error.value=e instanceof Error&&e.name!=='AbortError'?e.message:'读取超时，请重新读取加工历史。';}finally{clearTimeout(timer);if(gen===generation){loading.value=false;controller=null;}}}
function toggle(){expanded.value=!expanded.value;if(expanded.value)load();else clear();}
function change(){clear();if(expanded.value)load();}
function trace(r:any){requirementId.value=r.id;requirementVersion.value=r.version;change();}
function allRequirements(){requirementId.value='';requirementVersion.value=null;change();}
onBeforeUnmount(clear);
</script>
<template><section class="lab-history">
 <header class="lh-heading"><div><h4><History :size="17"/>加工办理经过</h4><p>{{requirementsTotal}}版要求 · {{handoversTotal}}次交接 · {{reviewsTotal}}次医生核对</p></div><button class="b-button outline small" :aria-expanded="expanded" @click="toggle">{{expanded?'收起办理经过':'查看办理经过'}}</button></header>
 <template v-if="expanded"><div class="lh-controls"><label>办理类别<select aria-label="加工办理类别" v-model="eventType" @change="change"><option v-for="(name,key) in labels" :key="key" :value="key">{{name}}</option></select></label><label>每页记录<select aria-label="每页加工历史" v-model="limit" @change="change"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label><button class="b-button outline small" :disabled="loading" @click="load()"><RefreshCw :size="14"/>重新读取</button></div>
 <p class="b-help">按系统登记先后倒序显示。实际交接、医生核对时间分别列出；历史“可用”只表示当次结论，当前有效状态见订单上方。人员标识固定，辅助姓名来自当前目录。</p><p v-if="requirementId" class="lh-filter">仅追查第{{requirementVersion}}版要求 · {{short(requirementId)}} <button class="f-text" @click="allRequirements">查看全部要求</button></p>
 <p v-if="loaded" class="lh-summary">已显示 {{items.length}} / {{total}} 次 · 读取时点 {{time(asOf)}}</p><div v-if="error" class="b-alert error" role="alert">{{error}}</div><p v-if="loading" role="status">正在读取加工历史…</p><p v-if="loaded&&!items.length" class="b-empty">当前筛选下没有加工办理记录。</p>
 <article v-for="r in items" :key="r.id" class="lh-event"><header><strong>{{labels[r.type]}}</strong><span v-if="r.orderVersion" class="b-pill">办理后订单版本 {{r.orderVersion}}</span></header><p class="lh-meta">系统登记 {{time(r.savedAt)}} · 操作人 {{r.editor.name}} · 操作 {{short(r.id)}}</p>
 <div class="lh-requirement"><strong>采用第{{r.requirement.version}}版要求</strong><span> · {{short(r.requirement.id)}} · {{r.requirement.doctor.name}}</span><p>{{r.requirement.text}}</p><small>要求登记 {{time(r.requirement.recordedAt)}} · 采用治疗版本 {{r.requirement.adoptedTreatmentVersion??'未留存'}} · 本版原预计返回 {{time(r.requirement.expectedReturnAt)}}</small><button v-if="!requirementId" class="f-text" @click="trace(r.requirement)">追查本版要求</button></div>
 <template v-if="r.phase"><p><strong>{{r.type==='review'?'医生核对时间':'实际交接时间'}}</strong> {{time(r.phase.occurredAt)}}</p><p>实际办理人员 {{people[r.phase.performerId]||r.phase.performerId}} <small class="lh-meta">{{r.phase.performerId}}</small></p><div class="lh-body">{{r.phase.content}}</div><p v-if="r.type==='received'">接收相符情况：<strong>{{match(r.phase.matchesRequirement)}}</strong></p><p v-if="r.type==='review'">当次临床结论：<strong>{{r.phase.isUsable?'核对可用':'不可用 / 待处理'}}</strong> · 采用接收 {{short(r.phase.receivedId)}}</p></template>
 <p v-else-if="r.type==='treatment_change'" class="lh-change">医生更正治疗依据，本订单的接收与临床核对依据随该操作失效，须更新加工要求。这里只追查加工影响，未展开病历正文。</p><p v-else-if="r.type==='requirement'" class="b-help">本版医生要求已保存；其后的交接和核对须采用本版要求。</p><div v-else class="lh-body">{{r.after?.progress_pending_note||r.reason||'本次未留存补充内容'}}</div>
 <details v-if="r.before||r.after" class="lh-states"><summary>查看本次前后依据</summary><div class="lh-state-grid"><div v-for="(s,i) in [r.before,r.after]" :key="i"><strong>{{i===0?'办理前':'办理后'}}</strong><template v-if="s"><p>进度：{{s.progress_pending_note||'未留存说明'}}</p><p>预计返回：{{time(s.current_expected_return_at)}}</p><p>接收依据：{{short(s.current_received_handover_id)}}</p><p>临床核对依据：{{short(s.current_review_id)}}</p><p>未解可用性问题：{{s.has_open_usability_issue?'有':'无'}}</p></template><p v-else-if="r.type==='requirement'">{{i===0?'首次提出要求，无前版订单。':'本次采用要求见上方；不以当前订单补造原状态。'}}</p><p v-else>本次治疗更正已使加工依据失效，原操作未保存完整后态快照。</p></div></div></details><details class="lh-ids"><summary>完整依据标识</summary><p>操作人 {{r.editor.id}}</p><p>操作 {{r.id}}</p><p>要求 {{r.requirement.id}}</p><p v-if="r.phase">阶段 {{r.phase.id}}</p><p v-if="r.phase?.receivedId">采用接收 {{r.phase.receivedId}}</p></details>
 </article><button v-if="next" class="b-button outline" :disabled="loading" @click="load(true)">读取更早加工记录</button>
 </template>
</section></template>
<style scoped>
.lab-history{margin-top:18px;padding-top:18px;border-top:1px solid #dce7e1;min-width:0;font-size:15px;line-height:1.7}.lh-heading,.lh-heading h4,.lh-controls,.lh-event header{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.lh-heading{justify-content:space-between}.lh-heading h4{font-size:16px;margin:0}.lh-heading p{font-size:13px;color:#61756f;margin:5px 0}.lh-controls{align-items:end;margin:20px 0 12px}.lh-controls label{display:grid;gap:6px;font-size:14px}.lh-controls select{padding:9px 12px;border:1px solid #cedbd5;border-radius:8px;background:white;max-width:100%}.lh-event{border:1px solid #dce7e1;border-radius:10px;padding:20px;margin:18px 0;overflow-wrap:anywhere}.lh-event header strong{font-size:16px;color:#176b52}.lh-meta,.lh-summary,.lh-requirement small,.lh-ids{font-size:13px;color:#61756f}.lh-requirement{background:#f3f8f5;padding:14px;border-radius:8px;margin:12px 0}.lh-requirement p,.lh-body{white-space:pre-wrap}.lh-requirement .f-text{display:block;padding:6px 0}.lh-body{padding:12px;background:#f7f9f8;border-radius:8px}.lh-change{padding:12px;background:#fff7e5;border-radius:8px}.lh-event p{margin:9px 0}.lh-states summary,.lh-ids summary{cursor:pointer;color:#176b52}.lh-states,.lh-ids{margin:14px 0}.lh-state-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:10px}.lh-state-grid>div{padding:12px;background:#f5f8f6;border-radius:8px}.lh-state-grid p{font-size:14px}.lab-history .b-help{font-size:14px}.lh-filter{padding:10px;background:#edf5f0;border-radius:8px}@media(max-width:760px){.lh-event{padding:14px}.lh-state-grid{grid-template-columns:minmax(0,1fr)}.lh-controls label{min-width:0;max-width:100%}.lh-heading{align-items:flex-start}}
</style>
